SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE title=VALUES(title), eyebrow=VALUES(eyebrow), description=VALUES(description), subtitle=VALUES(subtitle), product_count=VALUES(product_count), comparison_count=VALUES(comparison_count), price_range=VALUES(price_range), top_pick=VALUES(top_pick), top_score=VALUES(top_score), image_url=VALUES(image_url), image_key=VALUES(image_key), alt_text=VALUES(alt_text), updated_label=VALUES(updated_label), sort_order=VALUES(sort_order);

DELETE FROM category_criteria;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name=VALUES(name), brand=VALUES(brand), price=VALUES(price), price_display=VALUES(price_display), subscription=VALUES(subscription), score=VALUES(score), verdict=VALUES(verdict), best_for=VALUES(best_for), image_url=VALUES(image_url), image_key=VALUES(image_key), alt_text=VALUES(alt_text), merchant_name=VALUES(merchant_name), merchant_url=VALUES(merchant_url), updated_label=VALUES(updated_label), rank_order=VALUES(rank_order), is_featured=VALUES(is_featured);

DELETE FROM product_tags;

DELETE FROM product_specs;

SELECT id, verdict, JSON_ARRAY(image_url), JSON_ARRAY(), JSON_ARRAY(), JSON_ARRAY(),
  JSON_ARRAY(JSON_OBJECT('title','What it is','body',verdict),JSON_OBJECT('title','Best for','body',best_for)),
  STR_TO_DATE(CONCAT('01 ', updated_label), '%d %b %Y'), STR_TO_DATE(CONCAT('01 ', updated_label), '%d %b %Y'), 'Quarterly review', NULL
FROM products
ON DUPLICATE KEY UPDATE summary=VALUES(summary), gallery_json=VALUES(gallery_json), sections_json=VALUES(sections_json);

UPDATE product_reviews SET
  summary='Whisker''s fourth-generation self-cleaning litter box with app-based usage and health monitoring.',
  quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','Litter type','value','Clumping only'),JSON_OBJECT('label','Noise','value','~47 dB'),JSON_OBJECT('label','Warranty','value','18 months'),JSON_OBJECT('label','Subscription','value','Optional')),
  strengths_json=JSON_ARRAY('Globe design fully separates waste','App health tracking identifies usage changes','Large waste drawer','Quiet enough for bedroom placement','No proprietary litter required'),
  limitations_json=JSON_ARRAY('$699 entry price','Clumping litter only','Opening can be tight for very large cats','Optional odor consumables add cost','Pinch-detect false positives can interrupt cycles'),
  sections_json=JSON_ARRAY(
    JSON_OBJECT('title','What it is','body','The Litter-Robot 4 uses a rotating globe to separate clumps and deposits waste into a sealed drawer.'),
    JSON_OBJECT('title','Reliability','score',4.6,'body','Most reported interruptions are pinch-detect false positives and are commonly resolved by re-leveling or cleaning.'),
    JSON_OBJECT('title','App & connectivity','score',4.0,'body','The Whisker app tracks cycles and usage patterns. Historical health data beyond the base window requires the optional plan.'),
    JSON_OBJECT('title','Noise and placement','score',4.2,'body','Cycling noise is approximately 47 dB at one meter.'),
    JSON_OBJECT('title','Long-term cost','score',4.1,'body','The high entry price is partly offset by lower litter waste; odor pods remain optional.')
  ),
  research_date='2026-08-14', price_checked_date='2026-09-01', next_review_label='November 2026', source_count=11
WHERE product_id=(SELECT id FROM products WHERE slug='litter-robot-4');

ON DUPLICATE KEY UPDATE verdict=VALUES(verdict), home_verdict=VALUES(home_verdict), views_count=VALUES(views_count), read_time=VALUES(read_time), updated_label=VALUES(updated_label), content_json=VALUES(content_json), sort_order=VALUES(sort_order), is_featured=VALUES(is_featured);

DELETE FROM comparison_best_for;

DELETE FROM comparison_criteria;

ON DUPLICATE KEY UPDATE title=VALUES(title),pick_product_id=VALUES(pick_product_id),pick_name=VALUES(pick_name),budget=VALUES(budget),tradeoff=VALUES(tradeoff),image_url=VALUES(image_url),image_key=VALUES(image_key),content_json=VALUES(content_json),sort_order=VALUES(sort_order);

ON DUPLICATE KEY UPDATE title=VALUES(title),description=VALUES(description),read_time=VALUES(read_time),updated_label=VALUES(updated_label),image_url=VALUES(image_url),image_key=VALUES(image_key),content_json=VALUES(content_json),sort_order=VALUES(sort_order);

ON DUPLICATE KEY UPDATE product_id=VALUES(product_id),product_name=VALUES(product_name),problem=VALUES(problem),title=VALUES(title),description=VALUES(description),difficulty=VALUES(difficulty),estimated_time=VALUES(estimated_time),views_count=VALUES(views_count),updated_label=VALUES(updated_label),content_json=VALUES(content_json),sort_order=VALUES(sort_order);

DELETE FROM troubleshooting_steps;

ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);

ON DUPLICATE KEY UPDATE title=VALUES(title),description=VALUES(description),content_json=VALUES(content_json);
