INSERT INTO categories
  (slug, title, eyebrow, description, subtitle, product_count, comparison_count, price_range, top_pick, top_score, image_url, image_key, alt_text, updated_label, sort_order)
VALUES
  ('automatic-litter-boxes','Automatic Litter Boxes','Products / Automatic Litter Boxes','Self-cleaning systems for single and multi-cat households, ranked by reliability and long-term cost.','Self-cleaning units for single and multi-cat households. We document reliability, app quality, noise levels, and the full cost of ownership — upfront and ongoing.',34,'3','$179–$699','Litter-Robot 4',4.3,'https://images.unsplash.com/photo-1574158622682-e40e69881006?w=600&h=400&fit=crop&auto=format','categories/automatic-litter-boxes.webp','Cat next to a modern automatic litter box','Aug 2026',1),
  ('smart-pet-feeders','Smart Pet Feeders','Products / Smart Pet Feeders','Portion-controlled and camera-enabled feeders for dogs and cats, tested for dispensing accuracy.','Portion-controlled and camera-enabled feeders for dogs and cats. We test dispensing accuracy, scheduling flexibility, and long-term reliability.',28,'3+','$50–$130','PETLIBRO Granary',4.2,'https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=600&h=400&fit=crop&auto=format','categories/smart-pet-feeders.webp','Dog eating from an automatic feeder','Sep 2026',2),
  ('gps-pet-trackers','GPS Pet Trackers','Products / GPS Pet Trackers','Real-time location devices compared on coverage, battery life, subscription cost, and app reliability.','Real-time location devices compared on coverage area, battery life, subscription cost, and app reliability. We flag US-only limitations clearly.',19,'3+','$50–$150','Fi Series 3',4.1,'https://images.unsplash.com/photo-1548199973-03cce0bbc87b?w=600&h=400&fit=crop&auto=format','categories/gps-pet-trackers.webp','Dog wearing a GPS tracker collar outdoors','Aug 2026',3),
  ('pet-cameras','Pet Cameras','Products / Pet Cameras','Two-way audio, treat dispensing, and night vision — evaluated for video quality and app stability.','Two-way audio, treat dispensing, and night vision — evaluated for video quality, app stability, and real-world performance for managing pet anxiety.',22,'3+','$35–$169','Furbo 360°',4.0,'https://images.unsplash.com/photo-1537151608828-ea2b11777ee8?w=600&h=400&fit=crop&auto=format','categories/pet-cameras.webp','Cat being monitored by a home pet camera','Jul 2026',4)
INSERT INTO category_criteria (category_id, title, description, icon, sort_order) VALUES
((SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Number of cats','Single-cat households can use any unit. Two or more cats need a larger waste drawer and faster cycle recovery.','🐱',1),
((SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Litter type','Most automatic boxes require clumping litter. Crystal-tray units are the main exception.','🪣',2),
((SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Total cost of ownership','Compare the unit price with ongoing litter, tray, filter, bag, and subscription costs.','💰',3),
((SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'App and connectivity','App-connected units can expose usage trends, but app reliability varies significantly.','📱',4),
((SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Noise level','Prioritize models below 50 dB for bedrooms and open living spaces.','🔊',5),
((SELECT id FROM categories WHERE slug='smart-pet-feeders'),'Dispensing accuracy','Variance at small portions matters most for diet-prescribed pets.','⚖️',1),
((SELECT id FROM categories WHERE slug='smart-pet-feeders'),'Scheduling flexibility','Some units cap meals per day; others support per-meal intervals.','📅',2),
((SELECT id FROM categories WHERE slug='smart-pet-feeders'),'Camera quality','1080p with night vision is standard; some cameras are add-on accessories.','📷',3),
((SELECT id FROM categories WHERE slug='smart-pet-feeders'),'Power backup','Dual power prevents missed meals during outages.','🔌',4),
((SELECT id FROM categories WHERE slug='smart-pet-feeders'),'App reliability','A missed schedule is more serious than a missed notification.','📱',5),
((SELECT id FROM categories WHERE slug='gps-pet-trackers'),'Coverage area','US-only LTE-M and global cellular coverage suit different owners.','🌍',1),
((SELECT id FROM categories WHERE slug='gps-pet-trackers'),'Battery life','Battery life ranges from two days to three months.','🔋',2),
((SELECT id FROM categories WHERE slug='gps-pet-trackers'),'Monthly cost','Most GPS trackers require a subscription; compare annual cost.','💰',3),
((SELECT id FROM categories WHERE slug='gps-pet-trackers'),'Update frequency','Live tracking intervals materially affect recovery speed and battery life.','📍',4),
((SELECT id FROM categories WHERE slug='gps-pet-trackers'),'Health metrics','Some trackers include activity, sleep, and calorie data.','❤️',5),
((SELECT id FROM categories WHERE slug='pet-cameras'),'Field of view','Fixed lenses miss room corners; pan-and-tilt models cover more space.','📐',1),
((SELECT id FROM categories WHERE slug='pet-cameras'),'Night vision','Color night vision gives more usable detail than basic infrared.','🌙',2),
((SELECT id FROM categories WHERE slug='pet-cameras'),'Two-way audio','Speaker quality and latency determine whether pets respond.','🔊',3),
((SELECT id FROM categories WHERE slug='pet-cameras'),'Treat tossing','Treat range, capacity, and supported treat size vary.','🍬',4),
((SELECT id FROM categories WHERE slug='pet-cameras'),'Subscription cost','Check which alerts and recordings are locked behind a plan.','💰',5);
INSERT INTO products
  (external_id, category_id, slug, name, brand, price, price_display, subscription, score, verdict, best_for, image_url, image_key, alt_text, merchant_name, merchant_url, updated_label, rank_order, is_featured)
VALUES
('lr4',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'litter-robot-4','Litter-Robot 4','Whisker',699.00,'$699','Optional $12.49/mo',4.3,'The most reliable automatic litter box we''ve researched, with the best app-based health monitoring.','Multi-cat households (2–4 cats)','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=600&h=440&fit=crop&auto=format','products/litter-robot-4.webp','Litter-Robot 4','Litter-Robot','https://www.litter-robot.com/litter-robot-4.html','Aug 2026',1,TRUE),
('pura-x',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'petkit-pura-x','PETKIT PURA X','PETKIT',549.00,'$549','None',4.0,'Enclosed globe with quieter motor than the PURA MAX; good app with multi-cat weight identification.','Owners with 2 cats who want app health tracking','https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=600&h=440&fit=crop&auto=format','products/petkit-pura-x.webp','PETKIT PURA X','Amazon','https://www.amazon.com/s?k=PETKIT+PURA+X','Sep 2026',2,FALSE),
('pura-max',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'petkit-pura-max','PETKIT PURA MAX','PETKIT',399.00,'$399','None required',3.9,'Solid mid-range option with a competitive feature set at nearly half the Litter-Robot price.','Budget-conscious single-cat owners','https://images.unsplash.com/photo-1592194996308-7b43878e84a6?w=600&h=440&fit=crop&auto=format','products/petkit-pura-max.webp','PETKIT PURA MAX','Amazon','https://www.amazon.com/s?k=PETKIT+PURA+MAX','Aug 2026',3,FALSE),
('lr3',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'litter-robot-3-connect','Litter-Robot 3 Connect','Whisker',499.00,'$499','Optional $12.49/mo',3.9,'Previous-gen Litter-Robot — still reliable and available refurbished from Whisker.','Litter-Robot buyers on a tighter budget','https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=600&h=440&fit=crop&auto=format','products/litter-robot-3-connect.webp','Litter-Robot 3 Connect','Litter-Robot','https://www.litter-robot.com/litter-robot-iii-open-air-with-connect.html','May 2026',4,FALSE),
('catlink',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'catlink-luxury-pro-x','CATLINK Luxury Pro X','CATLINK',499.00,'$499','None',3.8,'Globe-style unit similar to Litter-Robot with more color options; app is less refined.','Owners wanting Litter-Robot style at lower cost','https://images.unsplash.com/photo-1548802673-380ab8ebc7b7?w=600&h=440&fit=crop&auto=format','products/catlink-luxury-pro-x.webp','CATLINK Luxury Pro X','CATLINK','https://www.catlinkus.com/','Jun 2026',5,FALSE),
('scoopfree',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'petsafe-scoopfree-ultra','PetSafe ScoopFree Ultra','PetSafe',179.00,'$179','$28–35/mo (crystal trays)',3.6,'Best entry price; crystal litter trays mean excellent odor control but higher monthly costs.','Single-cat owners preferring crystal litter','https://images.unsplash.com/photo-1513245543132-31f507417b26?w=600&h=440&fit=crop&auto=format','products/petsafe-scoopfree-ultra.webp','PetSafe ScoopFree Ultra','PetSafe','https://www.petsafe.com/shop/cat/litter-boxes-and-litter/','Jul 2026',6,FALSE),
('fi-s3',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'fi-series-3','Fi Series 3','Fi',149.00,'$149','$8.25/mo',4.1,'Best battery life in the category with reliable US LTE-M coverage.','US-based owners with active or escape-prone dogs','https://images.unsplash.com/photo-1548199973-03cce0bbc87b?w=600&h=440&fit=crop&auto=format','products/fi-series-3.webp','Fi Series 3','Fi','https://tryfi.com/','Aug 2026',1,TRUE),
('tractive',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'tractive-gps-dog-4','Tractive GPS DOG 4','Tractive',49.99,'$49.99','$12.99/mo',3.9,'Affordable hardware with coverage in 175+ countries.','International travelers and cost-sensitive buyers','https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=600&h=440&fit=crop&auto=format','products/tractive-gps-dog-4.webp','Tractive GPS DOG 4','Tractive','https://tractive.com/en/pd/gps-tracker-dog','Aug 2026',2,FALSE),
('whistle',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'whistle-go-explore','Whistle GO Explore','Whistle',79.95,'$79.95','$9.95/mo',3.8,'GPS plus health tracking in one device for the US and Canada.','Health-conscious owners in North America','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=600&h=440&fit=crop&auto=format','products/whistle-go-explore.webp','Whistle GO Explore','Amazon','https://www.amazon.com/s?k=Whistle+GO+Explore+GPS','Jul 2026',3,FALSE),
('jiobit',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'jiobit-smart-tag','Jiobit Smart Tag','Jiobit',99.99,'$99.99','$8.99/mo',3.6,'Ultra-compact and lightweight for small dogs and cats.','Small dogs and cats under 10 lb','https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=600&h=440&fit=crop&auto=format','products/jiobit-smart-tag.webp','Jiobit Smart Tag','Jiobit','https://www.jiobit.com/','Jun 2026',4,FALSE),
('petlibro',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'petlibro-granary','PETLIBRO Granary','PETLIBRO',89.99,'$89.99',NULL,4.2,'Best dispensing accuracy we''ve tested (±2%), a 1080p camera, and flexible scheduling.','Pets on medically prescribed portion-control diets','https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=600&h=440&fit=crop&auto=format','products/petlibro-granary.webp','PETLIBRO Granary','PETLIBRO','https://petlibro.com/collections/automatic-pet-feeder','Sep 2026',1,TRUE),
('petkit',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'petkit-fresh-element-infinity','PETKIT Fresh Element Infinity','PETKIT',129.99,'$129.99',NULL,3.9,'A desiccant drying system keeps dry food fresh longer.','Owners in humid climates or with food-storage concerns','https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=600&h=440&fit=crop&auto=format','products/petkit-fresh-element-infinity.webp','PETKIT Fresh Element Infinity','PETKIT','https://www.petkit.com/collections/automatic-pet-feeder','Sep 2026',2,FALSE),
('petsafe',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'petsafe-healthy-pet-simply-feed','PetSafe Healthy Pet Simply Feed','PetSafe',99.99,'$99.99',NULL,3.8,'Slow-feed mode and reliable scheduling without an app.','Owners who want a reliable no-app feeder','https://images.unsplash.com/photo-1513245543132-31f507417b26?w=600&h=440&fit=crop&auto=format','products/petsafe-healthy-pet-simply-feed.webp','PetSafe Healthy Pet Simply Feed','PetSafe','https://www.petsafe.com/shop/','Jul 2026',3,FALSE),
('arf',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'arf-pets-feeder','Arf Pets Automatic Feeder','Arf Pets',54.99,'$54.99',NULL,3.7,'Reliable for standard schedules, with more variance at small portions.','Owners needing a basic schedule feeder without a camera','https://images.unsplash.com/photo-1548802673-380ab8ebc7b7?w=600&h=440&fit=crop&auto=format','products/arf-pets-feeder.webp','Arf Pets Automatic Feeder','Amazon','https://www.amazon.com/s?k=Arf+Pets+Automatic+Pet+Feeder','Aug 2026',4,FALSE),
('furbo',(SELECT id FROM categories WHERE slug='pet-cameras'),'furbo-360','Furbo 360°','Furbo',169.00,'$169','$8.99/mo',4.0,'The best all-round pet camera with 360° pan, color night vision, and clear audio.','Dog owners managing separation anxiety','https://images.unsplash.com/photo-1537151608828-ea2b11777ee8?w=600&h=440&fit=crop&auto=format','products/furbo-360.webp','Furbo 360°','Furbo','https://furbo.com/us/products/furbo-360-dog-camera','Jul 2026',1,TRUE),
('petcube',(SELECT id FROM categories WHERE slug='pet-cameras'),'petcube-bites-2','Petcube Bites 2','Petcube',89.99,'$89.99','$4.99/mo',3.8,'Lower price and subscription with adequate treat tossing.','Cat owners and budget-conscious buyers','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=600&h=440&fit=crop&auto=format','products/petcube-bites-2.webp','Petcube Bites 2','Petcube','https://petcube.com/bites-2-lite/','Jul 2026',2,FALSE),
('eufy',(SELECT id FROM categories WHERE slug='pet-cameras'),'eufy-pet-camera-e220','eufy Pet Camera E220','eufy',79.99,'$79.99',NULL,3.7,'Pan-and-tilt with local storage and no mandatory subscription.','Owners who prefer local storage over cloud subscriptions','https://images.unsplash.com/photo-1548802673-380ab8ebc7b7?w=600&h=440&fit=crop&auto=format','products/eufy-pet-camera-e220.webp','eufy Pet Camera E220','eufy','https://www.eufy.com/products/t8410121','Jun 2026',3,FALSE),
('wyze',(SELECT id FROM categories WHERE slug='pet-cameras'),'wyze-cam-v3','Wyze Cam v3','Wyze',35.99,'$35.99',NULL,3.5,'The best budget option for basic live video and cloud storage.','Owners who just want live video without a subscription','https://images.unsplash.com/photo-1592194996308-7b43878e84a6?w=600&h=440&fit=crop&auto=format','products/wyze-cam-v3.webp','Wyze Cam v3','Wyze','https://www.wyze.com/products/wyze-cam-v3','Jun 2026',4,FALSE)
