INSERT INTO product_reviews (product_id, summary, gallery_json, quick_specs_json, strengths_json, limitations_json, sections_json, research_date, price_checked_date, next_review_label, source_count)
INSERT INTO comparisons
  (slug, category_id, product_a_id, product_b_id, product_a_name, product_b_name, verdict, home_verdict, views_count, read_time, updated_label, content_json, sort_order, is_featured)
VALUES
('litter-robot-4-vs-petkit-pura-max',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),(SELECT id FROM products WHERE slug='litter-robot-4'),(SELECT id FROM products WHERE slug='petkit-pura-max'),'Litter-Robot 4','PETKIT PURA MAX','Litter-Robot 4 is the more reliable long-term choice; PETKIT PURA MAX offers a lower entry price with competitive features.','Litter-Robot 4 for reliability; PETKIT for budget.',41200,'9 min read','Aug 2026',JSON_OBJECT('method','Identical criteria and current ownership costs'),1,TRUE),
('tractive-gps-vs-fi-series-3',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),(SELECT id FROM products WHERE slug='tractive-gps-dog-4'),(SELECT id FROM products WHERE slug='fi-series-3'),'Tractive GPS','Fi Series 3','Tractive works globally and suits travelers; Fi Series 3 has superior US network coverage and a longer battery life.','Tractive for international travel; Fi for US coverage.',28500,'8 min read','Aug 2026',JSON_OBJECT('method','Coverage, battery, tracking, and annual cost'),2,TRUE),
('petlibro-granary-vs-arf-pets-feeder',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),(SELECT id FROM products WHERE slug='petlibro-granary'),(SELECT id FROM products WHERE slug='arf-pets-feeder'),'PETLIBRO Granary','Arf Pets Feeder','PETLIBRO edges ahead on dispensing consistency across all portion sizes; Arf Pets is adequate for standard schedules at a lower price.','PETLIBRO wins on dispensing accuracy at all portion sizes.',19300,'7 min read','Sep 2026',JSON_OBJECT('method','Portion consistency, scheduling, power, and camera'),3,TRUE),
