  (slug,category_id,category_label,title,description,read_time,updated_label,image_url,image_key,content_json,sort_order)
VALUES
('how-to-choose-automatic-litter-box',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Litter Boxes','How to choose an automatic litter box','The five questions to answer before spending $200–$700 on a self-cleaning unit. Covers cat count, litter type, noise tolerance, and total cost of ownership.','8 min read','Aug 2026',(SELECT image_url FROM categories WHERE slug='automatic-litter-boxes'),'guides/how-to-choose-automatic-litter-box.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Start with your cats','body','Match the entrance, weight range, cycle recovery, and drawer capacity to the number and size of your cats.'),JSON_OBJECT('title','Check litter compatibility','body','Most rotating systems require clumping litter.'),JSON_OBJECT('title','Calculate twelve-month cost','body','Include litter, bags, filters, trays, and optional subscriptions.'))),1),
('gps-tracker-subscription-costs-explained',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'GPS Trackers','GPS tracker subscription costs, explained','Why every GPS tracker requires a subscription, what is typically locked behind the paywall, and how to calculate the real annual cost before buying.','6 min read','Aug 2026',(SELECT image_url FROM categories WHERE slug='gps-pet-trackers'),'guides/gps-tracker-subscription-costs-explained.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Why a plan is required','body','Cellular location reporting uses a carrier connection.'),JSON_OBJECT('title','Compare annual cost','body','Add hardware, activation, and the minimum usable plan.'))),2),
('clumping-vs-crystal-litter',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'Litter Boxes','Clumping vs. crystal litter: which is cheaper long-term?','Crystal trays have a lower upfront cost per tray but higher monthly cost than clumping brands. We run the numbers for 1, 2, and 3-cat households.','5 min read','Jul 2026','https://images.unsplash.com/photo-1513245543132-31f507417b26?w=600&h=380&fit=crop&auto=format','guides/clumping-vs-crystal-litter.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Monthly cost','body','Crystal trays prioritize convenience; clumping litter generally costs less over time.'),JSON_OBJECT('title','Compatibility','body','Use only the litter types supported by the device manufacturer.'))),3),
('pet-feeder-dispensing-accuracy',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'Feeders','Why dispensing accuracy matters (and how to test it)','A 10% variance on a 5g portion is clinically significant for a diet-controlled pet. Here is how to measure it.','7 min read','Sep 2026',(SELECT image_url FROM categories WHERE slug='smart-pet-feeders'),'guides/pet-feeder-dispensing-accuracy.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Run repeated trials','body','Weigh at least ten identical portions and calculate the range and average.'),JSON_OBJECT('title','Test your actual kibble','body','Shape and size affect every dispensing mechanism.'))),4),
('pet-camera-separation-anxiety-guide',(SELECT id FROM categories WHERE slug='pet-cameras'),'Cameras','Pet cameras and separation anxiety: what actually helps','Two-way audio can comfort some dogs and stress others. We explain which features reduce anxiety and which mainly reassure owners.','9 min read','Jul 2026',(SELECT image_url FROM categories WHERE slug='pet-cameras'),'guides/pet-camera-separation-anxiety-guide.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Observe the response','body','Stop remote audio if hearing a disembodied voice increases pacing or barking.'),JSON_OBJECT('title','Use alerts as evidence','body','Track patterns and discuss persistent distress with a qualified professional.'))),5),
('wifi-vs-cellular-pet-tracker',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'GPS Trackers','Wi-Fi triangulation vs. cellular GPS: what is the difference?','Fi Series 3 uses both; Tractive uses cellular. We explain where each technology works and fails.','6 min read','Aug 2026',(SELECT image_url FROM categories WHERE slug='gps-pet-trackers'),'guides/wifi-vs-cellular-pet-tracker.webp',JSON_OBJECT('sections',JSON_ARRAY(JSON_OBJECT('title','Wi-Fi zones save battery','body','Known Wi-Fi can indicate that a pet remains at home without continuous GPS.'),JSON_OBJECT('title','Cellular moves locations','body','A cellular link sends GPS positions when a pet leaves known coverage.'))),6)
